/* FANUC PRIO alarm codes — generated by tools/fetch-alarms.js,
 * DO NOT EDIT; re-run the tool instead. 266 codes, 2026-10-22.
 * Source: http://linuxsand.info/fanuc/ — internal reference copy, by permission. */
(function (global) {
  var data = {
    "001": "PRIO-001 Illegal port type code\nCause:  The port type code specified is invalid. This error code can be returned by several of the Digital I/O-related builtins\n(e.g., SET_PORT_ASG) when an invalid port type code is supplied.\nRemedy:  Use one the port types defined in IOSETUP.KL.",
    "002": "PRIO-002 Illegal port number\nCause:  The port number is invalid or not presently assigned. Port numbers must be in the range of 1-32767. However,\noperator panel (SOP) port numbers can be zero. In most cases (e.g., DOUT[n] = Off and calls to the SET_PORT_SIM\nbuiltin), the specified port already must be assigned.\nRemedy:  Correct the port number.",
    "003": "PRIO-003 No memory available\nCause:  Memory required for this operation is not available.\nRemedy:  Delete unneeded KAREL programs and/or variables to free memory.",
    "004": "PRIO-004 Too few ports on module\nCause:  There are not enough ports on the specified board or module to make the specified assignments. This error code can be\nreturned from the SET_PORT_ASG built-in.\nRemedy:  Correct either the first port number or the number of ports.",
    "005": "PRIO-005 bad port number\nCause:  The specified port number in an assignment is invalid. Port numbers must be in the range of 1 - 32767.\nRemedy:  Correct the port number so that it is within the valid range.",
    "006": "PRIO-006 bad port number\nCause:  The specified port number in an assignment (e.g., DIN[1] = ON) is invalid. The port number must be in the range of 1\n- 32767.\nRemedy:  Correct the port number so that it is within the valid range.",
    "007": "PRIO-007 No match in SET_PORT_ASG de-assign\nCause:  This error code is returned by the KAREL built-in SET_PORT_ASG when it is used as ade-assign request (with a\nphysical port type of zero) and the logical ports specified are not presently assigned.\nRemedy:  Correct the port number.",
    "008": "PRIO-008 physical ports not found\nCause:  The physical port to which ports are being assigned in a SET_PORT_ASSIGN built-in call does not exist.\nRemedy:  Correct the rack number, slot number, port type, or port number.",
    "009": "PRIO-009 number of ports invalid\nCause:  The number of ports in a SET_PORT_ASG call is invalid. This must be in the range of 1 - 128 for digital port types\n(e.g., DIN), 1-16 for groups, and 1 for analog port types.\nRemedy:  Correct the number of ports, so that it is within the valid range.",
    "010": "PRIO-010 bad physical port number\nCause:  An invalid physical port number is specified in a call to the KAREL built-in SET_PORT_ASG. This must be greater\nthan 0.\nRemedy:  Correct the physical port number, so that it is greater than 0.",
    "011": "PRIO-011 Assignment overlaps existing one\nCause:  The port numbers in a SET_PORT_ASG call overlap existing assignments.",
    "012": "PRIO-012 Bad board address\nCause:  The rack and/or slot number specified in a call of the KAREL built-in SET_PORT_ASG is invalid or refers to an\nunused rack/slot number.\nRemedy:  Correct the rack and/or slot number.",
    "013": "PRIO-013 No analog input sequence for bd\nCause:  An attempt was made to delete an analog input sequence that has not been defined.\nRemedy:  Check the rack and/or slot number and that an analog input sequence has previously been defined.",
    "014": "PRIO-014 Analog input sequnce too long\nCause:  The specified analog input sequence is too long; sequences must have from 1 to 15 ports numbers.\nRemedy:  Supply a sequence of an appropriate length.",
    "017": "PRIO-017 I/O point not simulated\nCause:  Attempt to set the state of an input port that is not simulated.\nRemedy:  Use the I/O menu or the SET_PORT_SIM KAREL built-in to set the port simulated or do not set the port.",
    "020": "PRIO-020 I/O Link comm error %x, %x, %x, %x (hex)\nCause:  Indicates that an error has been detected in communication between the MAIN CPU PCB and the process I/O board,\nModel-A I/O racks, or Model-B I/O interface units. The most common causes of this are the following: o Power to a\nremote I/O rack or Model-B I/O interface unit is interrupted. o The cable between the MAIN CPU PCB and the\nprocess I/O board, racks, or Model-B interface units has been disconnected or is faulty. o Electrical interference\nbetween the I/O cables and other cables. This can be eliminated by physically separating the I/O cables from other\nwiring. In very electrically noisy environments, it might be necessary to use optical isolators with these cables.\nRemedy:  Check the cabling between the MAIN CPU PCB (JB-18 connector) and the process I/O board and/or model A or B\ninterface modules. Check power to the remote Model A I/O racks and model B I/O interface modules. If corrections to\nthese do not correct the problem, check the four numbers displayed in this error message. The first value must be\ninterpreted bit-wise. If a bit is 1, the corresponding condition has been detected: Bit 0: (CFER) A CRC or framing\nerror has been detected by the SLC-2 chip on the MAIN CPU PBC. This is most frequently the result of the problems\nlisted above. Otherwise, it might indicate faulty SLC-2 chip, wiring between this and the JB-1B connector on the main\nPCB, or faulty process I/O, model-A I/O rack, or model-B interface unit. Bit 1: (CALM) An error has been detected by\na slave SLC-2 (process I/O board, Model-A rack, or Model B interface unit). More information is provided by the\nsecond number displayed with the PRIO-020 error. Bit 2: (CMER) A communication error has been detected by a\nslave SLC-2. The potential causes are similar to those for a CFER. Bit 3: (IPRER): Internal parity error accessing\nSLC-2 internal RAM. This indicates a faulty SLC-2 chip. In this case, the third and fourth numbers displayed with the\nPRIO-020 error is the address and and data for which the error was detected. This indicates a faulty SLC-2 chip. Bit 4:\n(OPRER): Parity error accessing external RAM by the SLC-2 chip. This might indicate bad DRAM or CMOS memory\non the MAIN CPU PCB. Bit 5: (ALMI): Indicates an alarm signaled from outside the SLC-2. Check the controller\nAlarm Log for other errors reported. Bit 6: (BSY): Auto scan is running. This might be either 0 or 1 and does not\nindicate an error. Bit 7: (CEND): Auto-scan cycle has completed. This might be either 0 or 1 and does not indicate an\nerror. The second number displayed is significant only if the CMER bit above is one. Bits 0-4: Indicate the position in\nthe I/O Link chain of the slave unit in which error was detected. A value of 1 indicates the unit connected directly to\nthe I/O LINK connector. Bit 5 (CFER): Indicates a CRC or framing error detected by the slave SLC-2. The causes are\nsimilar to those for a CFER error detected by the MAIN CPU SLC-2. Bit 6 (ALMI): Indicates an error asserted outside\nthe slave SLC-2. This may indicate a problem with process I/O board, model-B I/O rack, or model-B interface unit\nhardware. Bit 7 (SYALM): Indicates a watchdog alarm or parity error detected by the slave SLC-2. This may indicate\na problem with the process I/O board, model-A rack, or model-B interface unit.",
    "021": "PRIO-021 Unknown I/O hardware\nCause:  An unknown device is connected to the I/O Link connector. This device is not recognized by the current controller\nsoftware version.\nRemedy:  Replace the device with a device that is compatible with the current software or install a version of software that\nrecognizes the device.",
    "022": "PRIO-022 Too much I/O data on I/O link\nCause:  The devices connected to the I/O Link exceed the I/O link capacity. A total of 64 bytes of data each are available for\ninput and output devices connected to the I/O link. Process I/O boards typically use 16 bytes of input and 16 bytes of\noutput each. Digital modules generally use one byte for each 8 ports. Analog modules generally use two bytes per port.\nRemedy:  Disconnect some devices.",
    "023": "PRIO-023 No ports of this type\nCause:  There are no ports of the type (e.g., GIN) specified in an I/O statement or built-in call.\nRemedy:  Change the port type, add I/O hardware with the required type of ports, or define ports (e.g., GIN or GOUT) of the\nspecified type.",
    "033": "PRIO-033 PLC interface init. fault %d\nCause:  The PLC interface board is bad or not installed.\nRemedy:  Check that the PLC interface board is properly installed. Check the LED status on PLC interface board.",
    "034": "PRIO-034 PLC interface general fault %d\nCause:  The PLC interface board is faulted.\nRemedy:  Check the LED status on the PLC interface board.",
    "035": "PRIO-035 PLC interface serial fault %d\nCause:  The serial link to a PLC has failed.\nRemedy:  Check the LED status on PLC interface board.",
    "037": "PRIO-037 Not supported for spec. port type\nCause:  The operation is not supported for the specified port type.\nRemedy:  Check the specified port type.",
    "063": "PRIO-063 Bad I/O asg: rack %d slot %d\nCause:  One or more assignments to the process I/O board or module at the specified rack and slot was invalid when the\ncontroller was turned on.\nRemedy:  Check the connections and power to the board or rack and that the module(s) are firmly installed. If the board or\nmodule has been permanently removed, moved to a different Model A slot or had its switch settings changed (model\nB), use the CONFIG option on the Digital I/O menu to delete or update the assignment(s).",
    "070": "PRIO-070 PLC interface option not loaded\nCause:  An A-B RIO or Genius Network board is installed but the PLC software option is not installed.\nRemedy:  Install the PLC I/O (A-B/GENIUS) software option.",
    "072": "PRIO-072 Too many pulses active\nCause:  The maximum of number of concurrent pulse output statements is 255.\nRemedy:  Modify program logic to ensure that not over 255 pulses are active at one time.",
    "076": "PRIO-076 PLC I/O hardware not installed\nCause:  A PLC I/O board is not installed in the backplane.\nRemedy:  Install a PLC I/O board into the backplane.",
    "081": "PRIO-081 I/O is not initialized\nCause:  This indicates that an severe error has occurred during I/O initialization at controller power-up. Other messages in the\nlog will indicate the specific problems.\nRemedy:  Check other error messages displayed on the TP alarm screen. The conditions indicated by these messages need to be\ncorrected and the controller powered down and up before the robot can be used.",
    "083": "PRIO-083 Digital I/O is not recovered\nCause:  Digital output port states are not recovered when semi-hot start is enabled because I/O device configuration or\nassignments have changed. All outputs will be reset to OFF.\nRemedy:  Cold start the application.",
    "089": "PRIO-089 PMC is not supported on this hardware\nCause:  PMC function is not supported on this main board.\nRemedy:  Change main board or remove PMC function. If you need clear this alarm, please turn off K900.2 . PMC does not run\nat power up, and this alarm does not occur until you order to run PMC program.",
    "090": "PRIO-090 SNPX communication error\nCause:  Error occurs at SNPX communication.\nRemedy:  Please refer cause code.",
    "091": "PRIO-091 E-Stop PCB comm error %x, %x, %x (hex)\nCause:  Indicates that an error has been detected in communication between the MAIN PCB and Emergency stop PCB.\nRemedy: -  Check the cabling between the MAIN PCB and Emergency stop PCB.\n- Replace the cable between MAIN PCB and Emergency stop PCB.\n- Replace Emergency stop PCB.\n- Replace the MAIN PCB.",
    "092": "PRIO-092 Sensor comm error %x, %x (hex)\nCause:  This indicates that an error has been detected in communication circuit for Force sensor or Acceleration sensor on\nMAIN PCB.\nRemedy:  Replace the MAIN PCB.",
    "093": "PRIO-093 Fuse blown Rack:%d Slot:%d\nCause:  Fuse on process I/O board is blown.\nRemedy:  Please replace the fuse.",
    "094": "PRIO-094 Overload Rack:%d Slot:%d DO:%d-%d\nCause:  The specified DO may be grounded.\nRemedy:  Please check the connection of the specified DO.",
    "095": "PRIO-095 Overload %s\nCause:  The DO of the specified connector might be grounded.\nRemedy:  Check the connection of the DO of the specified connector.",
    "096": "PRIO-096 SNPX Connection is full<%s>\nCause:  The number of connections has reached the set value.\nRemedy:  Do any one of the following: Wait until a connection becomes vacant, Change the set value, or cycle power and begin\nthe beginning connection.",
    "097": "PRIO-097 SNPX time out<%s>\nCause:  No reply was received from the computer to which the displayed IP Address is set.\nRemedy:  Check the connection to the computer to which the displayed IP Address is set.",
    "098": "PRIO-098 PMC communication error\nCause:  Failed to PMC Ethernet communication.\nRemedy:  Please try to connect again.",
    "099": "PRIO-099 Port initialization error\nCause:  The port is initialized at PMC programmer.\nRemedy:  When use PMC Ethernet communication, disable PMC programmer in SETUP Port Init screen.",
    "100": "PRIO-100 Model B comm fault %srack:%d slot:%d\nCause:  Communication between the Model B interface unit and DI/DO units, or between DI/DO units, is lost.\nRemedy:  Check the power and cabling from Model B interface unit and DI/DO unit, or between DI/DO units.",
    "102": "PRIO-102 Cycle power to restart PLC I/O\nCause:  The PLC Interface hardware (A-B RIO or Genius Network PCB) is already running and can not be restarted without\ncycling power.\nRemedy:  Turn off and then turn on the controller.",
    "104": "PRIO-104 Device is off-line\nCause:  An attempt has been made to access to a port assigned to a device or board which is offline. This might be the result of\nan error or device having been set offline manually.\nRemedy:  For DeviceNet ports, troubleshoot as follows: Check the status of the DeviceNet board using the Digital I/O DeviceNet\nscreen. If the status field for the board is OFF, set it ONLINE. If the status is ERROR, check the following:\n1.)  The daughter board is installed on the Interface board.\n2.)  There is power on the network.\nIf these do not indicate a problem, set the board ONLINE. If the board is ONLINE, check the DEV LST screen entry\nfor the indicated device. If the status field for the device is OFF, set it ONLINE. If the status is ERROR, check the\nfollowing:\n1) The device is physically present on the network.\n2) The baud rate is set correctly.\n3) There are not devices with duplicate MAC-Ids on the network.\n4) The device with the required MAC-Id is the device type indicated in the DEV LST screen.",
    "106": "PRIO-106 Device with port is off-line\nCause:  An attempt was made to access a port assigned to a device which is offline. For DeviceNet ports, troubleshoot as\nfollows: This might be caused by an error or the device being manually set offline.\nRemedy:  First, determine the port type and number being accessed. Then use the appropriate Digital I/O CONFIG screen to\ndetermine the DeviceNet board and device MAC-Id to which the port is assigned. Check the status of the DeviceNet\nboard using the Digital I/O DeviceNet screen. If the status field for the board is OFF, set it ONLINE. If the status is\nERROR, check the following:\n1.)  The daughter board is installed on the Interface board.\n2.)  There is power on the network.\nAfter the problem is corrected, use the Digital I/O DeviceNet DEV LST screen to set the board ONLINE. If the board\nis ONLINE, check the DEV LST screen entry for the indicated device. If the status field for the device is OFF, set it\nONLINE. If the status is ERROR, check the following:\n1) The device is physically present on the network.\n2) The baud rate is set correctly.\n3) There are no devices with duplicate MAC-Ids on the network.\n4) The device with the required MAC-Id is the device type indicated in the DEV LST screen.\nOnce the problem is corrected, use the DEV LST screen to set the device ONLINE.",
    "119": "PRIO-119 Too many DIGITAL I/O ports\nCause:  There are too many DIGITAL I/O ports.\nRemedy:  Disconnect some DIGITAL I/O devices.",
    "121": "PRIO-121 Stop PMC program\nCause:  You can not do this operation when PMC program is running.\nRemedy:  Please stop PMC program execution.",
    "125": "PRIO-125 I/O Link initialization error\nCause:  The I/O Link is in an error state at the end of initialization.\nRemedy:  Please replace the device. If it is not remedied, please replace the cable. If not either, please replace the main board.",
    "126": "PRIO-126 PMC%d:No PMC program\nCause:  PMC program does not exit.\nRemedy:  Download PMC program.",
    "127": "PRIO-127 PMC file load error\nCause:  PMC program format is incorrect.\nRemedy:  Download PMC program again.",
    "128": "PRIO-128 T,C,K and D data may be lost\nCause:  Saving of keep relay (K), Timer (T), Counter (C) and Data table (D) at last power down is failed. Current data of them\nmay be old value.\nRemedy:  Load PARAM.PMC file.",
    "129": "PRIO-129 PMC%d:SUB%d is not supported\nCause:  Illegal function command is found in PMC program.\nRemedy:  Please check PMC program.",
    "130": "PRIO-130 PMC option is not installed\nCause:  Integrated PMC option is not installed.\nRemedy:  Please install Integrated PMC option.",
    "131": "PRIO-131 PMC file name error\nCause:  1. File name must be LADDER*.PMC or PARAM*.PMC. The other file name is used for save or load. 2. Device\nname to access is too long.\nRemedy:  1. Change file name to LADDER*.PMC for PMC program, PARAM*.PMC for PMC parameter file. 2. Make device\nname string short.",
    "132": "PRIO-132 PMC operation is locked\nCause:  One of the following is locked by another task. PMC program edit, DI/O port simulation change, PMC program\nbackup.\nRemedy:  Please try again later, or use the other method.",
    "133": "PRIO-133 PMC%d:PMC program size is too big\nCause:  Step of PMC program is too big.\nRemedy:  Please check PMC program step size.",
    "134": "PRIO-134 Invalid PMC addr %s%d.%d\nCause:  The specified PMC address is not valid for PMC.\nRemedy:  Please check the address in the PMC program.",
    "135": "PRIO-135 PMC address is not assigned\nCause:  Specified PMC address is not assigned to any device.\nRemedy:  Please check address in PMC program.",
    "136": "PRIO-136 PMC%d:BYTE access to %s%d.%d\nCause:  Specified PMC address can not be used as byte address.\nRemedy:  Please check address in PMC program.",
    "137": "PRIO-137 BIT access to %s%d.%d\nCause:  Specified PMC address can not be used as bit address.\nRemedy:  Please check address in PMC program.",
    "138": "PRIO-138 %s%d is used in SUB%d\nCause:  Specified address can not be used in specified function command. - F0-F255 and G0-G255 can not be used except\nMOVW. - Odd address of F0-F255 and G0-G255 can not be used in MOVW.\nRemedy:  Please check address in PMC program.",
    "139": "PRIO-139 Invalid CNC addr %x.%x(hex)\nCause:  Specified CNC address is invalid.\nRemedy:  Please check PMC program if any invaid address is used.",
    "140": "PRIO-140 Cant display all PMC errors\nCause:  There are more than 10 errors in PMC program. And error display is stopped. There may be more errors.\nRemedy:  Check the other PMC errors.",
    "141": "PRIO-141 PMC%d:Invalid PMC program\nCause:  PMC program data is invalid.\nRemedy:  Chack PMC program, and load again.",
    "142": "PRIO-142 Need E-STOP or CTRL start\nCause:  To write PMC program to flash file, E-SOP must be pressed or start mode is controlled start.",
    "143": "PRIO-143 Writting PMC program to ROM\nCause:  You can not clear alarm status during writing PMC program program to ROM.\nRemedy:  Press wait until writing PMC program is completed.",
    "144": "PRIO-144 Faild to run PMC program\nCause:  Faild to run PMC program.\nRemedy:  Refer to the previous error messages.",
    "145": "PRIO-145 Purging flash file, please wait\nCause:  Purging flash file now. It takes a few minutes. Dont cut power until Flash file purge is completed is displayed.\nRemedy:  It is message only.",
    "146": "PRIO-146 Flash file purge is completed\nCause:  Purge of flash file is completed.\nRemedy:  It is message only.",
    "147": "PRIO-147 DIO config file too new\nCause:  The DIO configuration file (.IO) file loaded is in a format that is too new to load on this controller.\nRemedy:  Save the DIO configuration on a compatible version and load this file.",
    "148": "PRIO-148 DIO config file too old\nCause:  The DIO configuration file (.IO) file loaded is in a format that is too old to load on this controller.\nRemedy:  Save the DIO configuration on a compatible version and load this file.",
    "149": "PRIO-149 Invalid assignment recorded\nCause:  An invalid port assignment has been recorded.\nRemedy:  No action is necessary; the invalid assignment will not be in effect until it is corrected or the DIO configuration is\nchanged.",
    "150": "PRIO-150 CNET Card Init Error Bd %d\nCause:  The ControlNet card failed to initialize. Possible problems can be the following. * The board system variable for\nfirmware is invalid. Correct the value or restore the system variables. * The board firmware is not supported. Restore\nsystem variables. If necessary reload the controller. * The card or the motherboard is defective.\nRemedy:  Look at possible causes. Remedies are mentioned therein.",
    "151": "PRIO-151 CNET Internal Error 0x%x\nCause:  ControlNet option encountered an internal error. The number is the system error in hexdecimal.\nRemedy:  Please look up the error to find the root cause.",
    "152": "PRIO-152 CNET Invalid Scan Config Bd %d\nCause:  The configuration loaded on the CNET daughterboard is invalid.\nRemedy:  Reload the configuration from the config tool. For adapter mode, verify that all parameters are correct. Verify that\nEDS files used for the config tool are valid. Verify that the configuration of the scan- list is valid in the config tool.",
    "153": "PRIO-153 CNET Conn. Ownership Conflict\nCause:  The target connection is already owned by some other device.\nRemedy:  Verify all connections to the target device from all scanners on the network. Inputs to a device cannot be multicast.",
    "154": "PRIO-154 CNET Duplicate Mac ID Bd %d\nCause:  Duplicate MAC-ID detected.\nRemedy:  Check MAC-IDs of all devices on the network.",
    "155": "PRIO-155 CNET Network Error Bd %d\nCause:  The CNET card is not attached to the network.\nRemedy:  Check wiring to the card. Check for duplicate MAC-ID. Ensure that there is at least one other device on the network.",
    "156": "PRIO-156 CNET Er %s Bd %d MAC %d\nCause:  The connection for the device Mac listed encountered an error. The Er number is the ControlNet error code.\nRemedy:  Refer to cause code if listed. If not, refer to the ControlNet error code in this manual or the ControlNet specification.",
    "157": "PRIO-157 CNET Err Loading BIN file Bd %d\nCause:  The firmware for the card could not be loaded.\nRemedy:  Refer to cause code. Verify Board sys vars to check for validity of values.",
    "158": "PRIO-158 CNET File Not Found\nCause:  The firmware file was not found.\nRemedy:  Verify Board sysvars $CN_BD_INFO[%d] are set correctly.",
    "159": "PRIO-159 CNET Cycle pwr to restart scan\nCause:  Scan list was modified. ControlNet interface is stopped.\nRemedy:  Cycle power to the controller for the changes to take affect.",
    "160": "PRIO-160 CNET Connections Broken Bd %d\nCause:  All connections to the card are broken. No I/O is exchanged and all ports are Offline. This happens when a network\nconfiguration is being performed or the Scan list is being changed.\nRemedy:  Finish the change. When the network is completed, the connections will be restored. If scan list is changed, the power\nwill have cycled for the interface to the restarted.",
    "161": "PRIO-161 CNET Network Change Occuring\nCause:  A config tool is performing a network change.\nRemedy:  Finish the change. When the network is completed, the connections will be restored. If scan list is changed, the power\nwill have cycled for the interface to the restarted.",
    "162": "PRIO-162 CNET Connections Restored Bd %d\nCause:  The CNET interface has restored the connections.\nRemedy:  This is a caution message to the user.",
    "163": "PRIO-163 CNET Network Change Complete\nCause:  The config tool has completed the network change.\nRemedy:  This is a caution message to the user.",
    "164": "PRIO-164 CNET Scan list modified Bd %d\nCause:  A config tool has modified the scan list of the interface card.\nRemedy:  At this point, a network config needs to performed using a network config tool such as RSNetworx.",
    "165": "PRIO-165 CNET Connection Not Found\nCause:  The interface could not establish a connection as it was not found.\nRemedy:  Verify the scan-list configuration and match it with the target device. Verify the connection paths. The connection path\nexpected by the scan- list can be found in the EDS file for the target device. The connection path supported by the\ntarget device can be found in its documentation. Verify that the target device and the EDS file used by the Scanner\nconfig match.",
    "166": "PRIO-166 CNET Invalid Connection Type\nCause:  Invalid connection type in scanlist.\nRemedy:  Use correct EDS file in the scan-list config tool and reload the scan-list.",
    "167": "PRIO-167 CNET Vend ID/Prod. Code Mismatch\nCause:  The vendor ID of the device in the scan-list and that of the actual device do not match.\nRemedy:  Use correct EDS file and reconfigure the scan-list of the CNET interface on the system.",
    "168": "PRIO-168 CNET Invalid Connection Size\nCause:  The connection size of the device in the scanlist does not match the target device.\nRemedy:  Verify correct size and reload the scan-list using the config tool.",
    "169": "PRIO-169 CNET Device Not Configured\nCause:  The connection has not been scheduled.\nRemedy:  Run a network configuration tool such as RSNetworx and configure the network.",
    "170": "PRIO-170 CNET Product Type Mismatch\nCause:  The Product Type of the device in the scan-list and that of the actual device do not match.\nRemedy:  Use correct EDS file and reconfigure the scan-list of the CNET interface on the system.",
    "171": "PRIO-171 CNET Maj/Min Revision Mismatch\nCause:  The Major/Minor revision of the device in the scan-list and that of the actual device do not match.\nRemedy:  Use correct EDS file and reconfigure the scan-list of the CNET interface on the system.",
    "172": "PRIO-172 CNET Target App Out of Conn.\nCause:  The target device does not have enough connections.\nRemedy:  Close some connections to target device.",
    "173": "PRIO-173 CNET Needs Network Config.\nCause:  The connection has not been scheduled.\nRemedy:  Run a network configuration tool such as RSNetworx and configure the network.",
    "174": "PRIO-174 CNET Connection Lost\nCause:  The connection to the remote device is lost.\nRemedy:  Check network connections. Check to see that the remote device is online. Check the status of the remote device.",
    "175": "PRIO-175 CNET Bad Device State\nCause:  The device is not in correct state to respond to this connection request.\nRemedy:  Run a network configuration tool such as RSNetworx and configure the network. Check if any other scanner has\nexisting connection to the device.",
    "176": "PRIO-176 CNET Connection Request Failed\nCause:  Remote device refused the connection. This could be due to an invalid connection path.\nRemedy:  Verify that the correct EDS file is being used for the device. Check the target device configuration.",
    "177": "PRIO-177 CNET Invalid configuration\nCause:  The Card has an invalid scan-list configuration.\nRemedy:  Check the configuration on the scanner config tool. Verify correct EDS files are used. Verify Input and Output sizes to\ndevices.",
    "178": "PRIO-178 Blk scns lost; %d %d %d\nCause:  A group of consecutive scans were lost; if n1=1, scans were lost on the main processor; if n1 = 2, scans were lost on\nthe communications processor; n2 = number of lost scans; if n2 is less than 5, this may not be a serious problem; n3 =\ntotal scans since pwr up since power-up. Generally indicates overloading of the indicated processor.\nRemedy:  Review software configuration to determine how loading can be reduced.",
    "179": "PRIO-179 Run scns lost; %d %d %d\nCause:  A group of scans were lost within a run of 100 scans. If n1=1, scans were lost on the main processor; if n1 = 2, scans\nwere lost on the communications processor; n2 = number of lost scans; if n2 is less than 20, this may not be a serious\nproblem; n3 = total scans since pwr up since power-up. Generally indicates overloading of the indicated processor.\nRemedy:  Review software configuration to determine how loading can be reduced.",
    "180": "PRIO-180 CNET Sys Err %d %d 0x%x\nCause:  An element could not be added to the system I/O scan When this error is posted, ControlNet I/O is not Operational.\nPossible causes are: * Invalid Configuration of scanner scan list * Too many I/O points for any given CNET device *\nToo many I/O points in the whole system.\nRemedy:  Verify all I/O is valid. Check all CNET devices and ensure the sizes are reasonable. Max I/O is limited by that allowed\nfor the system.",
    "181": "PRIO-181 CNET Conn. Req. Timeout\nCause:  Target device did not respond to the connection request.\nRemedy:  Verify that the target device is online and the status is OK. Verify that correct EDS file was used for the Scan-list\nconfiguration in the scanner configuration tool.",
    "182": "PRIO-182 CNET CCO Change Aborted\nCause:  Network change was aborted. Connections will be restored and I/O will be exchanged.\nRemedy:  This is a caution message.",
    "183": "PRIO-183 Unknown port type name\nCause:  Unrecognized port type name supplied to tpptnptc.\nRemedy:  Supply name from element tp_daio_tp_names_c in tpdaio*.utx.",
    "184": "PRIO-184 CNET Connection Idle\nCause:  The target (adapter) connection is idle. A scanner has not connected yet. All the ports corresponding to this device will\nbe offline.\nRemedy:  Check the remote scanner configuration. Check the sizes and other configuration parameters such as vendor ID,\nproduct code, product type, revision and connection path and verify they are correct. Verify that the scanner is online.",
    "185": "PRIO-185 CNET Config Er %d %d\nCause:  There is an error with the Scan-list configuration.\nRemedy:  Refer to the cause code.",
    "186": "PRIO-186 CNET Invalid Header size\nCause:  The input header size in case of scanner mode or the output header size in case of adapter is invalid.\nRemedy:  Enter a valid header size. The valid header is less that or equal to the total connection size. The total connection size is\na sum of the I/O size and the header size.",
    "187": "PRIO-187 CNET Invalid Num of Slots\nCause:  The number of slots for the device in the scan is invalid.\nRemedy:  Verify the configuration in the scanner config tool and reload the configuration. Verify that the EDS files are valid.",
    "188": "PRIO-188 Sim. Skip output not defined\nCause:  There is no output defined for the Simulated Input Skip feature and a WAIT instruction containing a skipped input is\nbeing executed.\nRemedy:  Define the Simulated Input Skip output using the System Config menu.",
    "189": "PRIO-189 (%s^4, %d^5) WAIT will time out\nCause:  The input used in this WAIT instruction is simulated and is designated as Skip When Simulated. This WAIT\ninstruction will timeout and program execution will proceed with the next line.\nRemedy:  None. This is only a warning to indicate that a Simulated Input Skip will occur.",
    "191": "PRIO-191 AB-RIO Board Init Error\nCause:  There was a problem initializing the AB-RIO hardware. The PRIO-191 alarm code will include a cause code with the\nreason.\nRemedy:\nNo Board : check that board is installed and dip switches are set properly.\nFailed to load/start/clear FW (firmware) : firmware file is missing or corrupt or possibly a problem with the\nhardware.",
    "192": "PRIO-192 AB-RIO No Board Found\nCause:  There was a problem initializing the AB-RIO hardware. The PRIO-191 alarm code will include a cause code with the\nreason.\nRemedy:\nNo Board : check that board is installed and dip switches are set properly.\nFailed to load/start/clear FW (firmware) : firmware file is missing or corrupt or possibly a problem with the\nhardware.",
    "193": "PRIO-193 AB-RIO Failed to Load FW\nCause:  There was a problem initializing the AB-RIO hardware. The PRIO-191 alarm code will include a cause code with the\nreason.\nRemedy:\nNo Board : check that board is installed and dip switches are set properly.\nFailed to load/start/clear FW (firmware) : firmware file is missing or corrupt or possibly a problem with the\nhardware.",
    "194": "PRIO-194 AB-RIO Failed to Start FW\nCause:  There was a problem initializing the AB-RIO hardware. The PRIO-191 alarm code will include a cause code with the\nreason.\nRemedy:\nNo Board : check that board is installed and dip switches are set properly.\nFailed to load/start/clear FW (firmware) : firmware file is missing or corrupt or possibly a problem with the\nhardware.",
    "195": "PRIO-195 AB-RIO Failed to Clear Config\nCause:  There was a problem initializing the AB-RIO hardware. The PRIO-191 alarm code will include a cause code with the\nreason.\nRemedy:\nNo Board : check that board is installed and dip switches are set properly.\nFailed to load/start/clear FW (firmware) : firmware file is missing or corrupt or possibly a problem with the\nhardware.",
    "196": "PRIO-196 AB-RIO Config Error, Slot %d\nCause:  There was a problem with a rack configuration. The slot will indicate which rack configuration. The problem might be\none of the following:\n1.  The rack number is not between 0 & 31.\n2.  The rack size or ending rack boundary is larger than the 128 I/O (full rack) maximum (eg. start group at 4 and a\nsize of more than half a rack).\nRemedy:  Correct the rack configuration on the AB-RIO user interface.",
    "197": "PRIO-197 AB-RIO Slot %d Idle\nCause:  The I/O connection associated with this slot is not actively exchanging I/O. Note that the alarm severity (STOP or\nWARN) is affected by the error severity setting on the AB-RIO configuration screen. The last state setting on this\nscreen affects the state of the inputs.\nRemedy:  Check the wiring, baud rate, and PLC configuration.",
    "198": "PRIO-198 AB-RIO Slot %d in Test/Prog\nCause:  The plc is in test mode, program mode, or the connection might be inhibited in the PLC. Note that the alarm severity\n(STOP or WARN) is affected by the error severity setting on the AB-RIO configuration screen. The last state setting\non this screen affects the state of the inputs.\nRemedy:  Check that the PLC is in run mode and that the connection is not inhibited in the PLC setup.",
    "200": "PRIO-200 FIPIO System Error %d\nCause:  An internal error has occurred.\nRemedy:  Note the number in the error message and contact the FANUC service representative.",
    "201": "PRIO-201 FIPIO PCB not installed\nCause:  The FIPIO PC104 board is not mounted on the PC104 motherboard or the PC104 motherboard is not mounted into the\noption slot on the backplane.\nRemedy:  Mount the FIPIO PC104 board on the PC104 motherboard and install the PC104 motherboard into the option slot on\nthe backplane.",
    "202": "PRIO-202 FIPIO PCB Abnormal\nCause:  FIPIO Circuit board is faulty.\nRemedy:  Replace the FIPIO circuit board.",
    "203": "PRIO-203 FIPIO Duplicate FIP Address\nCause:  Other device occupies the node address.\nRemedy:  Remove the device using the same address or change address from the FIPIO setup screen and cycle power on the\ncontroller.",
    "204": "PRIO-204 FIPIO Send Buffer Error\nCause:  An error occurred while sending data.\nRemedy:  Cycle power on the controller. Please contact the FANUC service representative if the problem persists.",
    "205": "PRIO-205 FIPIO Receive Buffer Error\nCause:  An error occurred while receiving data.\nRemedy:  Cycle power on the controller. Please contact the FANUC service representative if the problem persists.",
    "206": "PRIO-206 FIPIO Physical Reset\nCause:  The physical FIPIO node has been reset by PLC.\nRemedy:  To resume communication, press reset button on teach pendant or operation panel.",
    "207": "PRIO-207 FIPIO BadPrm; CMD %x,%x\nCause:  Error message from FIPIO PC104 agent board.\nRemedy:  Check whether the robot controller and PLC are wired correctly and try to cold start the robot controller. Please\ncontact the FANUC service representative if the problem persists. Note the numeric value(n) displayed with the error.\nThis data will be needed to further diagnose the problem.",
    "208": "PRIO-208 FIPIO NRDY; CMD %d LNG %d\nCause:  Bad communication status of FIPIO PC104.\nRemedy:  Check board address of FIPIO PC104 board. The value must be equal to $FIPIOVAR.$IO_ADDRESS that is\ndisplayed as decimal number, not hexadecimal. By default, the address is 0x330 (=816 in decimal). If the values are\nnot the same, change $FIPIOVAR.$IO_ADDRESS or address of FIPIO PC104 board to the same value. Next, make\nsure FIPIO PC104 board and PC104 motherboard are installed correctly. If all of above are correct and this alarm\noccurs continuously when the robot controller and PLC are properly connected, please contact the FANUC service\nrepresentative. Note the numeric values displayed with the error. This data will be needed to further diagnose the\nproblem.",
    "209": "PRIO-209 FIPIO Connection Broken\nCause:  1) Operating mode has been changed to IDLE or STOP by PLC. 2) Cable between the robot controller and PLC is\ndisconnected or faulty.\nRemedy:  1) Set operation mode to RUN by PLC 2) Check whether the robot controller and PLC is wired correctly.",
    "210": "PRIO-210 FIPIO Cnf/Adj not available\nCause:  N/A\nRemedy:  N/A",
    "211": "PRIO-211 FIPIO Bad Cnf/Adj status\nCause:  N/A\nRemedy:  N/A",
    "212": "PRIO-212 FIPIO Connection TimeOut\nCause:  The robot controller and PLC is not connected when the robot controller is turned on. When cable between the robot\ncontroller and PLC is disconnected after the initial connection is made, PRIO-209 STOP FIPIO Connection Broken\nerror will occur instead of this error.\nRemedy:  Check whether the robot controller and PLC are properly connected before the robot controller is turned on.",
    "213": "PRIO-213 FIPIO Connection Established\nCause:  Logical connection between the robot controller and PLC is established.\nRemedy:  This is only a warning message for the operator. This message is displayed when $FIPIOVAR.$POST_WARN system\nvariable is 1 (default:0).",
    "214": "PRIO-214 FIPIO Connection Recovered\nCause:  The operation mode has changed from IDLE or SECU to ACTIVE.\nRemedy:  This is only warning message for the operator. This message is displayed when $FIPIOVAR.$POST_WARN system\nvariable is 1 (default:0).",
    "230": "PRIO-230 EtherNet/IP Adapter Error (%d)\nCause:  The robot EtherNet/IP Adapter Connection running on the robot is enabled and has an error. Refer to additional cause\ncode text for further details.\nRemedy:  Alarm severity can be modified on the EtherNet/IP adapter configuration screen on a per connection basis, and last\nstate behavior can be modified with $EIP_CFG.$KEEP_IO_ADP. Refer to the EtherNet/IP Operators Manual for\nmore information.",
    "231": "PRIO-231 EtherNet/IP Adapter Idle\nCause:  The robot EtherNet/IP Adapter connection is enabled but no remote scanner has connected to it. Note that it is normal\nto see this message when the controller first is turned on since the remote scanner (eg. PLC) might not connect to the\nrobot immediately after the robot has been turned on. The PLC will retry the connection again so normally the\nconnection is made shortly after power up.\nRemedy:  Configure the remote scanner (eg. PLC) to connect to the robot. Press RESET to clear alarm. An alarm will be\nreposted if the connection is still idle.",
    "232": "PRIO-232 EtherNet/IP Not Initialized\nCause:  The robot EtherNet/IP Adapter was not able to initialize.\nRemedy:  This alarm generally implies that the Ethernet or TCP/IP interface is not set up correctly. For example, if no IP address\nis defined, then EtherNet/IP cannot initialize. Verify network connectivity using the ping utility (on the robot and also\non the local PC). If the problem persists, document the events that led to the alarm, and call your FANUC technical\nrepresentative.",
    "233": "PRIO-233 EtherNet/IP Scn Not in Run Mode\nCause:  A remote EtherNet/IP scanner is connected to the robot adapter in IDLE or program mode. No I/O data will be\ncommitted.\nRemedy:  Put the remote scanner in run mode, and retry the operation.",
    "280": "PRIO-280 FL-net System Error(%d)\nCause:  An internal error occurred.\nRemedy:  Please contact the FANUC service. Note the numeric value displayed with the error. This data will be needed to\nfurther diagnose the problem.",
    "281": "PRIO-281 FL-net PCB not installed\nCause:  The FL-net board is not properly mounted on the controller.\nRemedy:  If you want to use the FL-net function, insert the FL-net board properly. If you do not want to the FL-net function,\nclear the common memory and I/O settings for all nodes. This alarm is displayed when the I/O setting is configured for\nat least one node.",
    "282": "PRIO-282 FL-net PCB Abnormal(%d)\nCause:  The FL-net board does not function correctly.\nRemedy:  The FL-net board must be replaced. Please contact the FANUC service representative. Note the numeric value\ndisplayed with the error. This data will be needed when contacting service.",
    "283": "PRIO-283 FL-net IP Address Incorrect\nCause:  The specified IP address of my node does not belong to the class C.\nRemedy:  Specify the IP address of my node such that it belongs to the class C.",
    "284": "PRIO-284 FL-net Token Interval Error\nCause:  A time-out occurred in transmission from my node.\nRemedy:  Increase the value of the token monitoring time on the setting screen or decrease the amount of data to be transmitted\nfrom my node so that no time-out occurs in transmission from my node. Alternatively, another device may be causing\na slow response on the network. Check whether my node is affected by such a device.",
    "285": "PRIO-285 FL-net Init Error\nCause:  An error was detected in the FL-net connection sequence.\nRemedy:  Check whether all settings are correct. If this error continues to occur after verifying that all settings are correct, save\nthe setting data in FLNET.SV and send the file to a FANUC service representative.",
    "286": "PRIO-286 FL-net Wait Frame Status\nCause:  My node is in the frame reception wait state because there are no other nodes in the network or my node can recognize\nany other nodes.\nRemedy:  To start communication, add another node to the network. If my node does not recognize the other node, check\nwhether the robot and remote communication devices are connected to the network properly and are configured\ncorrectly.",
    "287": "PRIO-287 FL-net My Node Dupulicate No.\nCause:  Some other node has the same node number as my node.\nRemedy:  Change the node number of my node or the node which has the same node number. To change the node number of my\nnode, enter the least significant digit of the IP address on the my node setting screen. After changing the node number,\ncycle power on the robot controller.",
    "288": "PRIO-288 FL-net My Node Leave network\nCause:  My node was disconnected from the network. The cause may be loss of power or connection. In additional, my node\nmay be disconnected from the network due to another error which has occurred.\nRemedy:  Turn the power on and check whether my node can participate in the network and check whether the cables are\nconnected properly. Also check whether another error message has been posted. If another error message is posted,\nremove the cause of that error and try again.",
    "289": "PRIO-289 FL-net My Node Enter network\nCause:  My node has connected to the network.\nRemedy:  This only a warning message to alert the operator.",
    "290": "PRIO-290 FL-net My Node Dupulicate Adr\nCause:  The setting of common memory of another node overlaps the common memory area setting of my node.\nRemedy:  Change the common memory area setting for my node or the other node whose the common memory area overlaps my\nnode.",
    "291": "PRIO-291 FL-net Node %d Leave network\nCause:  The node with the node number displayed in the message was disconnected from the network.\nRemedy:  Check the node which was disconnected from the network by confirming the device settings and cable connection.\nAlso check whether another error message is posted. If another error message is posted, remove the cause of that error.\nPlease note that you can set the severity of this error to WARN or STOP for each node in the item for the error\nseverity on the detailed participating node setting screen.",
    "292": "PRIO-292 FL-net Node %d Enter network\nCause:  The node having the node number displayed in the message has connected to the network.\nRemedy:  This is only a warning message indicating the change in status to the operator.",
    "293": "PRIO-293 FL-net Dupulicate Area Adr %d\nCause:  The common memory area of a node overlaps that of the node with the node number displayed in the message.\nRemedy:  Change the setting of the common memory area to eliminate the overlap.",
    "294": "PRIO-294 FL-net Multiple PCBs detected\nCause:  Multiple FL-net boards are inserted into the controller.\nRemedy:  Remove additional FL-net boards. Only one can be inserted into the controller.",
    "295": "PRIO-295 FL-net register is too large\nCause:  FL-net sending register is too large or too small to change to integer.\nRemedy:  Change the register to smaller or larger value.",
    "296": "PRIO-296 FL-net board can’t use\nCause:  Setting is to use internal port for FL-net.\nRemedy:  Please use internal port or set to use board.",
    "297": "PRIO-297 FL-net rcv reg is too large\nCause:  FL-net receive register is too large.\nRemedy:  Set FL-net receive register under 200.",
    "320": "PRIO-320 CC-LK System error(ID=%x)(%d)\nCause:  An internal system error occurred.\nRemedy:  Contact FANUCs service site. The ID number in the brackets is necessary to track the problems.",
    "321": "PRIO-321 CC-LK Board not installed\nCause:  No CC-Link Remote Device Station PCB is installed.\nRemedy:  Install the CC-Link Remote Device Station PCB.",
    "322": "PRIO-322 CC-LK St.No out of range(%d)\nCause:  A station number out of the range (1 to 64) is occupied.\nRemedy:  Change the Station No. or Number of Stations on the CC-Link SETUP screen.",
    "323": "PRIO-323 CC-LK CRC error(%d)\nCause:  A CRC error was detected.\nRemedy:  Confirm the connection of CC-Link cable and terminal registers, and countermeasures to noise. Set the Baud rate to\nmatch the Master stations baud rate.",
    "324": "PRIO-324 CC-LK Data link error(%d)\nCause:  This Remote Device station left the data link. The CC-Link cable were disconnected or the Master station was turned\noff.\nRemedy:  Confirm the connection of CC-Link cable and the status of the Master station. Please note that if you turn on the\nRemote Device station while the CC-Link cable is disconnected or the Master station is off, this alarm will NOT be\nposted.",
    "325": "PRIO-325 CC-LK Seq. CPU stopped(%d)\nCause:  The sequencer CPU stopped.\nRemedy:  Confirm the status of the sequencer. Please note that this alarm is detected correctly only while the Remote Device\nstation is exchanging data with the Master station.",
    "326": "PRIO-326 CC-LK Seq. CPU abnormal(%d)\nCause:  The sequencer CPU is abnormal.\nRemedy:  Confirm the status of the sequencer. Please note that his alarm is detected correctly only while the Remote Device\nstation is exchanging data with the Master station.",
    "327": "PRIO-327 CC-LK Reg index error(%d)\nCause:  A non-existent register was used.\nRemedy:  Change Number of Registers or Reg start index on the CC-Link SETUP screen.",
    "328": "PRIO-328 CC-LK AO/R too many(%d)\nCause:  Too many AOs or Registers were assigned to RWr.\nRemedy:  Change the Number of AOs and Number of Registers on the CC-Link SETUP screen.",
    "329": "PRIO-329 CC-LK AI/R too many(%d)\nCause:  Too many AIs and Registers were assigned to RWw.\nRemedy:  Change Number of AIs and Number of Registers on the CC-Link SETUP screen.",
    "330": "PRIO-330 CC-LK PNTtoUOP not enough(%d)\nCause:  The number of points of RX/RY to be assigned to UOP are not enough.\nRemedy:  Change the Number of Stations on the CC-Link SETUP screen.",
    "331": "PRIO-331 CC-LK Reg data invalid(%d)\nCause:  A numerical value set to a remote register was not a 16 bit integer.\nRemedy:  \"CC-Link function of robot supports only unsigned or signed 16 bit word data. Do not enter another type of value into\na remote register.",
    "332": "PRIO-332 CC-LK no comm. to master(%d)\nCause:  Channel carrier detection error.\nRemedy:  Confirm the connection of CC-Link cable and terminal registers, and noise suppression. Set Baud rate to match the\nMaster stations baud rate.",
    "333": "PRIO-333 CC-LK comm task failed\nCause:  An internal system error has occurred.\nRemedy:  Contact a FANUC service representative.",
    "334": "PRIO-334 CC-LK too many boards found\nCause:  A) Three or more CC-Link daughter boards are installed. B) Three or more CC-Link Remote Device Station PCB are\ninstalled.\nRemedy:  Robot controller supports only two CC-Link communication boards. Turn off the controller and remove the excess\nboard(s).",
    "335": "PRIO-335 CC-LK different board types\nCause:  Two different types of CC-Link Remote Device Station PCBs are installed.\nRemedy:  The type of CC-Link Remote Device Station PCBs must be the same. Turn off the controller and remove all CC-Link\nboards of another type.",
    "350": "PRIO-350 EtherNet/IP Scanner Error (%d)\nCause:  The EtherNet/IP Scanner Connection running on the robot is enabled and has an error. Refer to additional cause code\ntext for further details.\nRemedy:  Alarm severity can be modified using the EtherNet/IP advanced scanner configuration screen on a per connection basis,\nand last state behavior can be modified with $EIP_CFG.$KEEP_IO_SCN. Refer to the EtherNet/IP Operators Manual\nfor more information.",
    "351": "PRIO-351 EtherNet/IP Cannot Open Socket\nCause:  The robot EtherNet/IP scanner was not able to open a TCP or UDP network socket.\nRemedy:  This alarm generally implies that the Ethernet or TCP/IP interface is not set up correctly. For example, if no IP address\nis defined, then the EtherNet/IP cannot initialize. Verify network connectivity using the ping utility (on the robot and\nalso on the local PC). If the problem persists, document the events that led to the alarm, and call your FANUC\ntechnical representative.",
    "352": "PRIO-352 EtherNet/IP Cannot Bind Socket\nCause:  The robot EtherNet/IP scanner was not able to bind a TCP or a UDP network socket.\nRemedy:  This alarm generally implies that the Ethernet or TCP/IP interface is not set up correctly. For example, if no IP address\nis defined, then the EtherNet/IP cannot initialize. Verify network connectivity using the ping utility (on the robot, and\nalso on the local PC). If the problem persists, document the events that led to the alarm, and call your FANUC\ntechnical representative.",
    "353": "PRIO-353 EtherNet/IP Send Error\nCause:  The robot EtherNet/IP scanner was not able to send information on a TCP or UDP network socket.\nRemedy:  This alarm generally implies that the Ethernet or TCP/IP interface is not set up correctly. For example, if no IP address\nis defined, then the EtherNet/IP cannot initialize. Verify network connectivity using the ping utility (on the robot and\nalso on the local PC). If the problem persists, document the events that led to the alarm, and call your FANUC\ntechnical representative.",
    "354": "PRIO-354 EtherNet/IP Cannot Resolve Name\nCause:  The robot EtherNet/IP scanner could not resolve the configured remote adapter hostname.\nRemedy:  Verify the Name/IP Address entered in the Scanner Configuration Screen is valid. Try to ping the address from the\nmain EtherNet/IP screen. If using DNS, verify that DNS is properly configured. If using the robot Host Name tables",
    "355": "PRIO-355 EtherNet/IP Connect Error\nCause:  The robot EtherNet/IP scanner was not able to connect to the adapter device on a TCP network socket.\nRemedy:  Verify the robot controller and the remote adapter device are both connected to the same network. Check the remote\nadapter device and verify it is running properly. Ping the remote adapter device from the robot. Press RESET to restart\nthe robot scanner connection. If the problem persists, document the events that led to the alarm, and call your FANUC\ntechnical representative.",
    "356": "PRIO-356 EtherNet/IP List Serv Failed\nCause:  The robot EtherNet/IP Scanner did not receive a List Services Reply message from the remote adapter.\nRemedy:  Verify the robot controller and the remote adapter device are both connected to the same network. Check the remote\nadapter device and verify it is running properly and verify that EtherNet/IP is enabled on the adapter. Ping the remote\nadapter device from the robot. Press RESET to restart the robot scanner connection.",
    "357": "PRIO-357 EtherNet/IP Reg Sess Failed\nCause:  The robot EtherNet/IP scanner did not receive a Register Session Reply message from the remote adapter.\nRemedy:  Check the remote adapter device and verify that EtherNet/IP is enabled. Press RESET to restart the robot scanner\nconnection.",
    "358": "PRIO-358 EtherNet/IP FwdOpen Fail (0x%x)\nCause:  The robot EtherNet/IP scanner either did not receive a ForwardOpen Reply message from the remote adapter, or the\nrobot scanner received a ForwardOpen Reply message from the remote adapter indicating a failure to establish an I/O\nconnection.\nRemedy:  Verify the scanner settings in the robots Scanner Configuration screen are correct--review the manual of the remote\nadapter device for the correct settings. Verify that the remote adapter does not currently have a duplicate explicit\nowner connection (another scanner device already connected to the same assembly instances). Check the remote\nadapter device and verify that EtherNet/IP is enabled, and that the device is accessible on the network. Take note of\nthe hexadecimal code in the robot alarm text and lookup the error in the robot scanner manual. Press RESET to restart\nthe robot scanner connection. The figure in the error message specifies the extended status of the error returned by the\ntarget device in hexadecimal format. The table below describes the extended status error codes.\nGENERAL STATUS  EXTENDED STATUS  DESCRIPTION\n0x01  0x0100  Connection in Use or Duplicate Forward Open.\n0x01  0x0103  Transport Class and Trigger combination not supported.\n0x01 0x0106 Ownership  Conflict.\n0x01  0x0107  Connection not found at target application.\n0x01  0x0108  Invalid Connection Type. Indicates a problem with either\nthe Connection Type or Priority of the Connection.\n0x01  0x0109  Invalid Connection Size.\n0x01  0x0110  Device not configured.\n0x01  0x0111  RPI not supported. Might also indicate problem with\nconnection timeout multiplier or production inhibit time.\n0x01  0x0113  Connection Manager cannot support any more\nconnections.\n0x01  0x0114  Either the Vendor Id or the Product Code in the key\nsegment did not match the device.\n0x01  0x0115  Product Type in the key segment did not match the\ndevice.\n0x01  0x0116  Major or Minor Revision information in the key segment\ndid not match the device.\n0x01  0x0117  Invalid Connection Point.\n0x01  0x0118  Invalid Configuration Format.\n0x01  0x0119  Connection request fails since there is no controlling\nconnection currently open.\n0x01 0x011A Target  Application cannot support any more\nconnections.",
    "359": "PRIO-359 EtherNet/IP I/O Timeout Error\nCause:  The robot EtherNet/IP Scanner timed-out while waiting for an I/O update message from the remote adapter.\nRemedy:  Press RESET to restart the scanner connection. Check the remote adapter to verify it is functioning properly.",
    "360": "PRIO-360 EtherNet/IP Adp Not in Run Mode\nCause:  The EtherNet/IP adapter to which the robot scanner is connected is in IDLE mode. No input data will be committed.\nRemedy:  Put the adapter in RUN mode.",
    "368": "PRIO-368 EtherNet/IP Could Not Go Online (%s)\nCause:  An unexpected system level error has occurred.\nRemedy:  Document the events that led to the error, and call your FANUC technical representative.",
    "369": "PRIO-369 EtherNet/IP System Error\nCause:  An unexpected system level error has occurred.\nRemedy:  Document the events that led to the error, and call your FANUC technical representative.",
    "490": "PRIO-490 Modbus TCP Server Error\nCause:  The Modbus TCP Server running on the robot is enabled and has an error. Refer to additional cause code text for\nfurther details.\nRemedy:  Alarm severity and last state behavior can be modified using the Modbus TCP Slave configuration screen. Refer to the\nModbus Setup and Operations Manual for more information.",
    "493": "PRIO-493 Modbus Socket Error\nCause:  The Modbus TCP Server was not able to open and use a TCP network socket.\nRemedy:  This alarm generally implies that the Ethernet or TCP/IP interface is not set up correctly. For example, if no IP address\nis defined, then the TCP/IP stack cannot initialize. Verify network connectivity using the ping utility (on the robot, and\nalso on the local PC).",
    "494": "PRIO-494 Modbus Active Close\nCause:  A Modbus TCP master device is trying to establish a connection with the robot Modbus slave, but the server is already\nusing all available connections. This is a warning alarm and will only be posted the first time this happens after each\npower-cycle. Per the Modbus TCP protocol, when a new connection request arrives and there are no unused\nconnections, the oldest connection will be closed, and the new connection request will be accepted.\nRemedy:  Increase the number of connections using the Modbus TCP screen.",
    "495": "PRIO-495 Modbus Timeout\nCause:  The Modbus TCP server timed-out while waiting for an I/O message from a Modbus TCP client.\nRemedy:  Check the Modbus TCP client to verify it is functioning properly. Adjust the robot Modbus TCP timeout if necessary.",
    "499": "PRIO-499 Modbus System Error\nCause:  Modbus TCP System Error. A general system failure has occurred.\nRemedy:  Turn off the controller, then turn it on again. If the error still occurs, document the events that led to the error and\ncontact your FANUC technical representative.",
    "520": "PRIO-520 PMC:Invalid Override setting\nCause:  Setting of Override is invalid. Override can be set for only tree nummber of PMC.\nRemedy:  Reduce number of PMCs setting Ovreride.",
    "521": "PRIO-521 PMC:Invalid seqence numbers\nCause:  Setting of Sequence number is invalid.\nRemedy:  Check Sequence number.",
    "522": "PRIO-522 PMC:Invalid memory types\nCause:  Setting of Memory Type is invalid.\nRemedy:  Check Memory Type.",
    "523": "PRIO-523 PMC%d:memory types are mismatch\nCause:  Setting of Memory Type is invalid.\nRemedy:  Check Memory Type.",
    "524": "PRIO-524 PMC:Invalid execution rates\nCause:  Setting of Execution Rates is invalid.\nRemedy:  Check Execution Rates.",
    "525": "PRIO-525 PMC%d:PARAM%d.PMC was not loaded\nCause:  PARAM*.PMC was not loaded. PMC adress values are not replaced.\nRemedy:  Please confirm setting of max PMC-path number.",
    "526": "PRIO-526 PMC%d:Keep data was not restored\nCause:  Keep data was not restored.\nRemedy:",
    "527": "PRIO-527 PMC:E relay data was not restored\nCause:  E relay data was not restored.\nRemedy:",
    "528": "PRIO-528 PMC%d:Step Sequence cannot be used\nCause:  Step Sequence program cannnot be used. It can be used only PMC1.\nRemedy:  Please load this PMC program as PMC1.",
    "529": "PRIO-529 PMC:PMC interface setting is invaled\nCause:  PMC interface adress(M,N) setting is invalid.\nRemedy:  Please change setting of PMC interface on PMC Setting screen.",
    "530": "PRIO-530 PMC%d:Function Block cannot be use\nCause:  Multi-Path PMC Option(J763) is not orderd. To use some function, J763 is needed.",
    "531": "PRIO-531 PMC%d:Invalid statements exist\nCause:  Some function statements can not be used.\nRemedy:  Please delete invvalid functions from PMC progarms.",
    "532": "PRIO-532 PMC%d:Int.I/O[%d] setting is overlaped with other IO assignment\nCause:  IO index setting is overlaped with other device. IO index of Int.I/O can not be used the same index.\nRemedy:  Please change setting of Int.I/O.",
    "533": "PRIO-533 PMC%d:Int.I/O[%d] IO is invalid\nCause:  IO index setting of Int.I/O is invalid.\nRemedy:  Please change setting of Int.I/O.",
    "534": "PRIO-534 PMC%d:Int.I/O[%d] size is invalid\nCause:  PMC address setting of Int.I/O is invalid. PMC address must be set as 2 byte alignment.\nRemedy:  Please change setting of Int.I/O.",
    "535": "PRIO-535 PMC%d:Int.I/O[%d] address is invalid\nCause:  PMC address setting of Int.I/O is invalid.\nRemedy:  Please change setting of Int.I/O.",
    "536": "PRIO-536 PMC%d:Number of Int.I/O is limit\nCause:  Number of Int.I/O setting is limit.\nRemedy:  Please change setting of Int.I/O.",
    "537": "PRIO-537 PMC:%s[%d] value cannot be copied(Int.I/O[%d])\nCause:  Error of Int.I/O Copy Mode. Register is not integer.\nRemedy:  Please change setting or change register value.",
    "538": "PRIO-538 PMC:Cycle power to change setting\nCause:  PMC Setting is changed.\nRemedy:  Please cycle power to change PMC setting.",
    "539": "PRIO-539 PMC:Temporary Memory is lack\nCause:  Temporary Memory to use PMC is lack.\nRemedy:  Please change PMC memory area size or use large memory.",
    "540": "PRIO-540 PMC%d:PMC programs are deleted at cycle power\nCause:  Setting of max PMC path number is changed. PMC program will be deleted at next cycle time.\nRemedy:  Please set back max PMC path number not to deleate PMC programs.",
    "541": "PRIO-541 PMC:LADDER%d.PMC was deleted\nCause:  PMC program was deleted, because setting of max path PMC number is changed.\nRemedy:",
    "542": "PRIO-542 PMC No ext. I/O rack:%d slot:%d\nCause:  The device that set to External I/O of PMC is not found.\nRemedy:  Please check setting of PMC External I/O. Check the connections of I/O modules.",
    "543": "PRIO-543 PMC:Can not use Ext. I/O assignment\nCause:  Internal X,Y address assignment and External I/O assignment can not be used together.\nRemedy:  Please delete setting of PMC External I/O. Or please delete Internal I/O setting of X and Y address.",
    "544": "PRIO-544 PMC:Can not use memory common mode\nCause:  Internal X,Y address assignment and setting of memory common mode can not be used together.\nRemedy:  Please change setting of memory type. Or please delete Internal I/O setting of X and Y address.",
    "545": "PRIO-545 PMC:Override cannot set this address\nCause:  PMC address assigned to Internal I/O cannot set as Override.\nRemedy:  Please use simulate value of I/O screen.",
    "600": "PRIO-600 PNIO board not installed\nCause:  PCI motherboard with PROFINET board is not installed.\nRemedy:  Check motherboard or PROFINET board are inserted firmly.",
    "601": "PRIO-601 PNIO watchdog alarm\nCause:  PROFINET software on the robot controller is not working.\nRemedy:  Cycle power the robot controller. Please contact FANUC customer service if this error occurs repeatedly.",
    "602": "PRIO-602 PNIO system error(ID=%x)(%d)\nCause:  System error.\nRemedy:  Please contact FANUC customer service. Report the value in the error message.",
    "603": "PRIO-603 %s\nCause:  An internal system error has occurred.\nRemedy:  Please contact FANUC customer service. Report the error message.",
    "604": "PRIO-604 PNIO SYSTEM error\nCause:  System error.\nRemedy:  Open alarm history screen because this error may show up together with another error message. Please contact\nFANUC customer service, and report the error message. When PROFINET Safety is used, PRIO-604 may show up\nwith PRIO-603 “PROFIsafe hard fail”, “CRC check error” or “status check error”. Then, first of all, check whether the\nconfiguration of safety PLC and the setting of robot controller matches. Check the size of safety input/output in DCS\nPROFINET Safety screen, configure the safety PLC again, and cycle power the robot controller. If the problem\npersists, the error is probably due to a hardware problem. Please contact FANUC customer service.",
    "605": "PRIO-605 PNIO(D) open error %04x\nCause:  Failed to start PROFINET I/O Device function. This error message may show up during remote configuration by PC\nconfiguration tool. This error message may show up when the robot controller is used only as I/O Device and its IP\naddress is supposed to be set by I/O Controller (such as PLC), but the I/O Controller has not started.\nRemedy:  The value in the error message is error code from PROFINET board. The value might be one of the followings.\nError Code  Meaning  Remedy\n0x0309  Wrong calling sequence  Wait for a while, or press reset. Then the\nrobot controller tries to start I/O Device again.\n0x030D  Config in update\nPROFINET board might be stopped\nby PC configuration tool for remote\nconfiguration.",
    "606": "PRIO-606 PNIO(D) abort indication %x\nCause:  PROFINET I/O communication is aborted by I/O Controller.\nRemedy:  This is just notification.",
    "607": "PRIO-607 PNIO(D) offline indication %x\nCause:  PROFINET I/O communication is stopped by I/O Controller.",
    "608": "PRIO-608 PNIO(D) mismatch slot %d %d\nCause:  Reported module with slot number and subslot number does not match the configuration of project file downloaded to\nI/O Controller.\nRemedy:  Check the setting in the setup module detail screen. Check the project file.",
    "609": "PRIO-609 PNIO: Need reset for restart\nCause:  PROFINET board is stopped by PC configuration tool when I/O Controller is enabled.\nRemedy:  Start PROFINET board by PC configuration tool and then press reset.",
    "610": "PRIO-610 PNIO(C) open error %04x\nCause:  Failed to start PROFINET I/O Controller function. This error message may show up when PROFINET board is\nstopped by PC configuration tool.\nRemedy:  The value in the error message is error code from PROFINET board. The value might be one of the followings.\nError Code  Meaning  Remedy\n0x0304  No configuration is available  Download XDB project file to PROFINET board in\ncontrolled start.\n0x0309  Wrong calling sequence  Press reset. Then the robot controller tries to start I/O\nController again.\n0x030D  Config in update\nPROFINET board might be stopped\nby PC configuration tool for remote\nconfiguration.",
    "611": "PRIO-611 PNIO(C) alarm indication %x\nCause:  Alarm is indicated by PROFINET board.\nRemedy:  This is just notification.",
    "612": "PRIO-612 PNIO(C) offline indication\nCause:  Operating mode is changed to offline.\nRemedy:  This is just notification.",
    "613": "PRIO-613 PNIO(C) clear indication\nCause:  Operating mode is changed to clear.\nRemedy:  This is just notification.",
    "614": "PRIO-614 PNIO watchdog start failed\nCause:  System error.\nRemedy:  Please contact FANUC customer service. Report the error message.",
    "615": "PRIO-615 PNIO: cant find the station\nCause:  Specified station number is not found when the switching TP instruction is executed.\nRemedy:  Check the station number.",
    "616": "PRIO-616 PNIO: attach/detach Timeout\nCause:  Then switching TP instruction has timed out.\nRemedy:  Check if the target station is connected well.",
    "617": "PRIO-617 PNIO(D) mod plug failed %x %x\nCause:  I/O Device function failed because the specified module is wrong.\nRemedy:  Check the module specified by two numbers, the former is slot number, the latter is subslot number.",
    "618": "PRIO-618 PNIO(D) submod plug failed %x %x\nCause:  I/O Device function failed because the specified submodule is wrong.\nRemedy:  Check the module specified by two numbers, the former is slot number, the latter is subslot number.",
    "619": "PRIO-619 PNIO(C) mismatch st %d slot %d %d\nCause:  The stored configuration of the module that is specified by station number, slot number and subslot number does not\nmatch the current configuration when the start mode is OPERATION.\nRemedy:  Check the parameters of the module that is specified by station number, slot number and subslot number.",
    "620": "PRIO-620 PNIO(C) station %d deactivated\nCause:  The device whose “Show error when deactivated” setting is ON is deactivated.\nRemedy:  Check the station specified by the station number, and activate it.",
    "621": "PRIO-621 PNIO(D) device is not running\nCause:  The start up of I/O Device has not completed or was terminated by an error.\nRemedy:  Disable I/O Device if I/O Device function is not used in setup general screen. If I/O Device function is used, check if\nany error related to I/O Device is present. Check if I/O Controller that is supposed to communicate with the robot\ncontroller is running. This error can be released when the setting of I/O Device is correct and communication to the\nI/O Controller establishes.",
    "622": "PRIO-622 PNIO(C) controller is not running\nCause:  The start up of I/O Controller has not completed or was terminated by an error.\nRemedy:  Disable I/O Controller if I/O Controller function is not used. If I/O Controller function is used, check if any error\nrelated to I/O Controller is present. This error can be released when the setting of I/O Controller is correct and\ncommunication to the I/O Devices establishes.",
    "623": "PRIO-623 PNIO(C) not in operation mode\nCause:  The start up of I/O Controller has completed but the start up mode is not OPERATION.\nRemedy:  Change the start mode to OPERATION, and cycle power on the robot controller.",
    "624": "PRIO-624 PNIO(C) mod number mismatch\nCause:  The number of modules in the stored configuration is different from the current configuration when the start mode is\nOPERATION.\nRemedy:  Check if the project downloaded to PROFINET board matches the current configuration, and if the configuration was\nread in by the robot controller in READ IN mode.",
    "625": "PRIO-625 PNIO(C) read in complete\nCause:  PROFINET network configuration has been read in successfully when start mode is READ IN.\nRemedy:  This is just notification of completion of read in. Check PROFINET I/O Controller communication and I/O data\nexchange before changing start mode to OPERATION.",
    "626": "PRIO-626 PNIO: please power OFF/ON\nCause:  PROFINET setting of the robot controller was changed and cycling power is required to enable the change.\nRemedy:  Cycle the power of the robot controller.",
    "627": "PRIO-627 PNIO: set to operation mode\nCause:  Start mode is changed to operation mode.\nRemedy:  This is just notification of completion of mode change.",
    "628": "PRIO-628 PNIO(C) group is not recovered\nCause:  The device switching status cannot be recovered.\nRemedy:  Restore each device by configuration screen or TP instruction.",
    "629": "PRIO-629 Restore group manually\nCause:  The device switching status cannot be recovered.\nRemedy:  Restore each device by configuration screen or TP instruction.",
    "630": "PRIO-630 PNIO(C) mod data out of area\nCause:  The data of a PROFINET I/O module is not placed inside of the area specified by the start address and the size for any\ntype of I/O, or it is placed across the border of some of the areas. In this case, the data is not allocated to any I/O.\nRemedy:  If the data need to be allocated to I/O of the robot controller, change the configuration in the robot controller, NCM/PC\nor STEP7 according to the information with PRIO-631 or PRIO-632. Please note that the data of a PROFINET I/O\nmodule can be allocated to only a single type of I/O (digital, analog, arc welding). It must be placed within the area\nspecified by the start address and the size for a type of I/O and it must not be placed across the border of any areas,\notherwise it is not allocated to any I/O. In such case, PRIO-630 appears at start up with PRIO-631 or PRIO-632 to\ninform which data is not allocated.",
    "631": "PRIO-631 IN: address (%d - %d)\nCause:  PRIO-631 appears with PRIO-630 to inform which data is not allocated.\nRemedy:  The first number is the start address of the input data from a PROFINET I/O module to the robot. The second number\nis the last address of the data. Check the configuration in the robot controller.",
    "632": "PRIO-632 OUT: address (%d - %d)\nCause:  PRIO-632 appears with PRIO-630 to inform which data is not allocated.\nRemedy:  The first number is the start address of the output data from the robot to a PROFINET I/O module. The second number\nis the last address of the data. Check the configuration in the robot controller.",
    "633": "PRIO-633 PNIO: Updating Firmware\nCause:  Firmware update of PROFINET board has started.\nRemedy:  Wait until firmware update is completed. Never turn off the robot controller during the download, otherwise the\nfirmware might be erased and PROFINET board is not operational until it is recovered. In such case, please refer to\nPRIO-635 for the procedure of recovery.",
    "634": "PRIO-634 PNIO: FW. updated\nCause:  Firmware update of PROFINET board has completed successfully.\nRemedy:  Cold start the robot controller.",
    "635": "PRIO-635 PNIO: FW. update failed\nCause:  Firmware update of PROFINET board has failed.\nRemedy:  Download can be retried. In case the firmware is erased. Set $PNIO_DL.$NO_FIRM_ST to 1, controlled start the\ncontroller, and write the firmware that is known to work well.",
    "636": "PRIO-636 PNIO: XDB downloaded\nCause:  XDB project file is downloaded to PROFINET board.\nRemedy:  This is just an information.",
    "637": "PRIO-637 PNIO: Cant open file\nCause:  The specified file cant be opened.\nRemedy:  Make sure the file name with device path (such as MC:) is correct.",
    "638": "PRIO-638 PNIO: Not enough memory\nCause:  There is not enough memory in COMM processor for this operation.\nRemedy:  Please contact FANUC customer service.",
    "639": "PRIO-639 PNIO: Unsupported feature\nCause:  Configuration of unsupported feature is found.\nRemedy:  Please see the cause code to know what is not supported. Change the configuration by remote configuration tool.",
    "640": "PRIO-640 IOPS=bad:api %x,st %d, %d,%d\nCause:  I/O producer status of the specified module of PROFINET I/O has turned to BAD. The figures in the message are API\nnumber, station number, slot number, and subslot number.\nRemedy:  Check the specified module.",
    "641": "PRIO-641 IOPS=good:api %x,st %d, %d,%d\nCause:  I/O producer status of the specified module of PROFINET I/O has turned to GOOD. The figures in the message are\nAPI number, station number, slot number, and subslot number.\nRemedy:  This is only notification of recovery.",
    "642": "PRIO-642 Alarm %x:api %x,st %d, %d,%d\nCause:  An alarm indication of PROFINET I/O has come. The figures in the message are alarm type, API number, station\nnumber, slot number, and subslot number.\nRemedy:  Check the alarm data of the specified module.",
    "643": "PRIO-643 PNIO(C) station %d activated\nCause:  The device specified by the alarm message is activated.\nRemedy:  This is just notification.",
    "644": "PRIO-644 PNIO msg too long ch=%d(%d/%d)\nCause:  The length of a PROFINET message from PROFINET board exceeds the limit.\nRemedy:  Check if the limit parameter is adequate. Locate the event that causes this alarm, and contact FANUC customer\nservice.",
    "645": "PRIO-645 PNIO: many unread alarm ind.\nCause:  The number of unread alarm indication gets too large. Alarm indication interface function is enabled but probably\nthere is no KAREL program that reads it out. Alarm indication should be read out because it uses memory while it is\nkept unread.\nRemedy:  Disable alarm indication interface function by setting bit2,3 of $PNIO_CFG2.$USHORT4 to 0. For example, if\n$PNIO_CFG2.$USHORT is 63 (0x3F), set 51 (0x33). Cycle power is needed to apply the change. Or create a KAREL\nprogram that reads out alarm indication. Please refer to Appendix A of PROFINET I/O Operator’s manual for more\ndetails.",
    "646": "PRIO-646 IOCS=bad:api %x,st %d, %d,%d\nCause:  I/O consumer status of the specified module of PROFINET I/O has turned to BAD. The figures in the message are API\nnumber, station number, slot number, and subslot number.\nRemedy:  Check the specified module.",
    "647": "PRIO-647 Check the specified module.\nCause:  I/O consumer status of the specified module of PROFINET I/O has turned to GOOD. The figures in the message are\nAPI number, station number, slot number, and subslot number.\nRemedy:  This is only notification of recovery.",
    "648": "PRIO-648 PNIO(C) Too many devices\nCause:  Too many devices exist in PROFINET project.\nRemedy:  Decrease the number of stations, I/O modules and interface modules.",
    "650": "PRIO-650 Too many I/O comments\nCause:  Too many I/O comments were set.\nRemedy:  Delete some unnecessary I/O coments."
  };
  if (typeof module !== 'undefined' && module.exports) module.exports = data;
  if (global.FanucAlarms) global.FanucAlarms._put("PRIO", data);
})(typeof window !== 'undefined' ? window : globalThis);
